      // （scripts2.js:17184-17197：循环 dataArr.length，dataArr[i] 作 numTime），
      // 而配置表 daily_active_tips 有 18 行（id 1..18，isshow>0 的才显示）→ 给 18 个 0 即渲染出 18 条"零进度"任务。
      var dataArr = [];
